import {money,numeric,escapeHTML as e,dateISO} from './finance.js';
import {categoryField,categoryForRecord,categoryOptions} from './categories.js';
import {pageHref} from './routes.js';
import {noticeDate} from './notices.js';
import {ensureBusiness,businessTotals,businessPaidDate,businessSales,businessRecordDeletion,deleteBusinessRecord,addBusinessRecord,settleBusinessRecord,addBusinessTax,payBusinessTax,ownerWithdrawal,businessCSV} from './business.js';
export function createBusinessUI(ctx){let section='overview';const {icon,modal,commit,toast,stat,panelHeader}=ctx;const get=()=>ensureBusiness(ctx.getData()),month=()=>ctx.getMonth();
 const field=(label,name,type='text',value='',attrs='',required=true)=>`<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${e(value)}" ${attrs} ${required?'required':''}></label>`;
 const dateLabel=v=>v?new Date(v+'T12:00:00').toLocaleDateString('pt-BR'):'—';
 function setSection(next){section=next||'overview';}
 function identity(){const p=get().profile;return `<div class="business-identity"><div class="business-avatar">${icon('business')}</div><div><h2>${e(p.name||'Seu negócio começa aqui')}</h2><p>${e(p.kind)}${p.cnpj?' · '+e(p.cnpj):' · Seu espaço de trabalho'}</p></div><button class="button secondary" data-business="profile">${icon('settings')}Perfil da empresa</button></div>`;}
 function render(){const b=get();return `${identity()}<nav class="business-tabs" aria-label="Áreas do negócio">${[['overview','Visão do negócio'],['records','Movimentações'],['pending','A receber e a pagar'],['taxes','Tributos']].map(([id,label])=>`<a href="${pageHref('business',id)}" data-business-tab="${id}" class="${section===id?'active':''}" ${section===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${!b.profile.name?`<div class="tip">${icon('business')}<div><strong>Dê um nome ao seu próximo capítulo.</strong><br>Preencha o perfil da empresa e o caixa inicial para começar a organizar o negócio.</div><button class="button secondary" data-business="profile">Cadastrar negócio</button></div>`:''}${({overview,records,cash,sales,pending,receivable:()=>pending('income'),payable:()=>pending('expense'),taxes}[section]||overview)()}`;}
 function overview(){const b=get(),t=businessTotals(b,month()),goal=b.profile.annual_goal,pct=goal?Math.min(100,t.annualRevenue/goal*100):0;return `<section class="stats" aria-label="Resumo do negócio">${stat('Caixa do negócio',t.closingBalance,'wallet',`${icon('lock')}Saldo acumulado até o fim do mês`,pageHref('business','cash'))}${stat('Vendas do mês',t.revenue,'invest',`${icon('calendar')}Pela data de cada venda`,pageHref('business','sales'))}${stat('A receber',t.receivable,'in',`${t.receivableCount} ${t.receivableCount===1?'recebimento pendente':'recebimentos pendentes'}`,pageHref('business','receivable'))}${stat('A pagar',t.payable,'up',`${t.payableCount} ${t.payableCount===1?'compromisso pendente':'compromissos pendentes'}`,pageHref('business','payable'))}</section><div class="business-grid"><section class="panel">${panelHeader('Um ano de trabalho, em números','Vendas cadastradas em '+month().slice(0,4),`<span class="tag">${month().slice(0,4)}</span>`)}${annualChart(b)}<div class="business-annual"><span>Vendas registradas no ano</span><b class="money">${money(t.annualRevenue)}</b></div>${goal?`<div class="progress"><span style="width:${pct}%"></span></div><div class="goal-values"><span>${Math.round(pct)}% da sua meta de vendas</span><b class="money">${money(goal)}</b></div>`:'<p class="form-note">Defina uma meta anual no perfil da empresa para acompanhar o progresso.</p>'}</section><aside class="agent-card business-assistant"><div class="agent-label"><span class="agent-mark">${icon('business')}</span>Seu negócio, com clareza</div><h2>Seu trabalho cresce.<br><em>Seu controle também.</em></h2><p>Organize o que entra, acompanhe o que falta receber e planeje as próximas contas.</p><div class="planning-actions"><button class="button light" data-plan="withdrawal">Simular retirada</button><button class="button light" data-business="withdrawal">Registrar retirada</button></div><div class="agent-foot">Planeje o caixa e veja o efeito no saldo pessoal</div></aside><section class="panel">${panelHeader('O caixa deste mês','Pela data em que o dinheiro entrou ou saiu')}<div class="business-cash-row"><span>${icon('in')}Recebimentos</span><b class="money positive">${money(t.received)}</b></div><div class="business-cash-row"><span>${icon('up')}Saídas e retiradas</span><b class="money">${money(t.spent)}</b></div><div class="business-cash-row total"><span>Saldo da empresa no mês</span><b class="money ${t.cashResult<0?'negative':'positive'}">${money(t.cashResult)}</b></div><p class="form-note">Retiradas do titular no mês: <span class="money">${money(t.withdrawals)}</span>. Resultado de caixa não representa lucro contábil.</p></section><section class="panel">${panelHeader('Próximos compromissos','O que ainda precisa de atenção',`<a class="text-button" href="${pageHref('business','pending')}">Ver pendências${icon('chevron')}</a>`)}${pendingRows().slice(0,3).map(pendingMini).join('')||'<div class="empty">Tudo em dia nos seus registros. 🌱</div>'}</section></div><div class="business-footnote">Resumo gerencial com os valores cadastrados. Receitas pessoais, caixa da empresa e metas têm controles próprios.</div>`;}
 function annualChart(b){const year=month().slice(0,4);const vals=Array.from({length:12},(_,i)=>businessTotals(b,`${year}-${String(i+1).padStart(2,'0')}`).revenue),max=Math.max(...vals,1);const labels=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];return `<div class="business-bars" role="img" aria-label="Vendas cadastradas por mês de ${year}">${vals.map((v,i)=>`<div class="business-bar-column"><div class="business-bar-track"><div class="business-bar ${month().slice(5)===String(i+1).padStart(2,'0')?'current':''}" style="height:${v?Math.max(3,v/max*100):2}%" title="${labels[i]}: ${money(v)}"></div></div><span>${labels[i]}</span></div>`).join('')}</div>`;}
 function deleteButton(record){
  if(record.linked&&!['withdrawal','tax'].includes(record.linked_type))return '';
  return `<button type="button" class="icon-button business-delete" data-business-delete="${e(record.id)}"
    aria-label="Excluir ${e(record.name)}" title="Excluir lançamento">${icon('trash')}</button>`;
 }
 function table(list, {rowDate = record=>record.date, dateLabelText = 'Data'} = {}){return `<div class="business-table-wrap"><table class="transaction-table full-table business-table"><thead><tr><th>Descrição / contato</th><th>${dateLabelText}</th><th>Situação</th><th>Valor</th><th>Ação</th></tr></thead><tbody>${list.map(r=>`<tr><td><div class="transaction-name"><span class="category-icon ${r.type==='income'?'receita':''}">${icon(r.linked_type==='withdrawal'?'in':r.type==='income'?'invest':'bag')}</span><div>${r.linked?`<strong>${e(r.name)}</strong>`:`<button class="business-edit-link" data-business-edit="${e(r.id)}">${e(r.name)}</button>`}<small>${e(r.counterparty||r.category)}</small>${r.import_sheet&&r.import_cell?`<small>Origem ${e(r.import_sheet)}!${e(r.import_cell)}</small>`:''}</div></div></td><td class="muted">${dateLabel(rowDate(r))}</td><td><span class="business-status ${r.status==='paid'?'paid':r.due_date<dateISO()?'overdue':''}">${r.status==='paid'?(r.type==='income'?'Recebido':'Pago'):r.due_date<dateISO()?'Em atraso':'Pendente'}</span></td><td class="money amount ${r.type==='income'?'positive':''}">${r.type==='income'?'+':'−'} ${money(r.amount)}</td><td><div class="business-record-actions">${r.status==='pending'?`<button class="text-button" data-business-settle="${e(r.id)}">${r.type==='income'?'Recebi':'Paguei'}${icon('check')}</button>`:r.linked?'<span class="tag">Vinculado</span>':`<button class="text-button" data-business-edit="${e(r.id)}">Editar</button>`}${deleteButton(r)}</div></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Nenhum registro neste período.<br>Adicione a primeira movimentação do seu negócio.</div></td></tr>'}</tbody></table></div>`;}
 function records(){const b=get();return `<section class="panel">${panelHeader('Movimentações da empresa','Vendas e despesas pela data do registro',`<button class="text-button" data-business="export">${icon('download')}Exportar CSV</button>`)}<div class="filter-bar"><label class="search">${icon('search')}<input class="input" id="business-search" placeholder="Buscar descrição, cliente ou fornecedor…" aria-label="Buscar movimentação empresarial"></label><select id="business-type-filter" aria-label="Filtrar tipo empresarial"><option value="all">Receitas e despesas</option><option value="income">Receitas</option><option value="expense">Despesas</option></select><select id="business-category-filter" aria-label="Filtrar por categoria"><option value="">Todas as categorias</option>${categoryOptions(ctx.getData(),'business')}</select><button type="button" class="button secondary" data-categories="business">Categorias</button></div><div id="business-record-results">${table(b.records.filter(r=>r.date.startsWith(month())).slice().sort((a,b)=>b.date.localeCompare(a.date)))}</div></section>`;}
 function cash(){
  const b=get(), totals=businessTotals(b,month());
  const rows=b.records.filter(record=>businessPaidDate(record)?.startsWith(month()))
    .sort((a,b)=>businessPaidDate(b).localeCompare(businessPaidDate(a)));
  const value=(label,amount)=>`<div class="business-cash-row"><span>${label}</span><b class="money">${money(amount)}</b></div>`;
  return `<section class="panel">${panelHeader('Caixa do negócio','Movimentações pela data de recebimento ou pagamento')}
   ${value('Saldo no início do mês',totals.openingBalance)}${value('Entradas recebidas',totals.received)}
   ${value('Saídas pagas',totals.spent)}${value('Saldo acumulado até o fim do mês',totals.closingBalance)}
   ${table(rows,{rowDate:businessPaidDate,dateLabelText:'Data da baixa'})}</section>`;
 }
 function sales(){
  const rows=businessSales(get(),month()).sort((a,b)=>b.date.localeCompare(a.date));
  const total=rows.reduce((sum,record)=>sum+record.amount,0);
  return `<section class="panel">${panelHeader('Vendas do mês','Vendas pela data do registro, incluindo as que ainda estão a receber',
   `<b class="money">${money(total)}</b>`)}${table(rows)}</section>`;
 }
 function pendingRows(){const b=get();return [...b.records.filter(r=>r.status==='pending').map(r=>({...r,entity:'record'})),...b.taxes.filter(t=>!t.paid).map(t=>({...t,entity:'tax',type:'expense',category:'Tributo',counterparty:t.competence}))].sort((a,b)=>a.due_date.localeCompare(b.due_date));}
 function pendingMini(r){return `<div class="business-pending-row"><span class="category-icon ${r.type==='income'?'receita':''}">${icon(r.type==='income'?'in':'calendar')}</span><div class="bill-info">${e(r.name)}<p>${r.type==='income'?'A receber':'A pagar'} · ${dateLabel(r.due_date)}${r.due_date<dateISO()?' · Em atraso':''}</p></div><div class="business-pending-value"><b class="money">${money(r.amount)}</b><button class="text-button" ${r.entity==='tax'?`data-business-taxpay="${e(r.id)}"`:`data-business-settle="${e(r.id)}"`}>${r.type==='income'?'Recebi':'Paguei'}</button>${r.entity==='record'?deleteButton(r):''}</div></div>`;}
 function pending(type){
  const rows=pendingRows();
  const pane=direction=>{
   const list=rows.filter(item=>item.type===direction);
   const receiving=direction==='income';
   const total=list.reduce((sum,item)=>sum+item.amount,0);
   const title=receiving?'A receber':'A pagar';
   const subtitle=receiving?'Recebimentos pendentes de todos os meses':'Contas e tributos pendentes por vencimento';
   const empty=receiving?'Nenhum recebimento pendente.':'Nenhuma conta pendente.';
   return `<section class="panel">${panelHeader(title,subtitle,`<b class="money">${money(total)}</b>`)}
     ${list.map(pendingMini).join('')||`<div class="empty">${empty}</div>`}</section>`;
  };
  return `${type?pane(type):`<div class="business-grid equal">${pane('income')}${pane('expense')}</div>`}
   <p class="form-note">Ao dar baixa, informe a data real do recebimento ou pagamento.</p>`;
 }
 function taxes(){const b=get(),mei=b.profile.kind==='MEI';return `<div class="business-grid"><section class="panel">${panelHeader(mei?'DAS e outros tributos':'Tributos do negócio','Competências e valores informados por você',`<button class="button secondary" data-business="tax">${icon('plus')}Adicionar tributo</button>`)}${b.taxes.slice().sort((a,b)=>b.competence.localeCompare(a.competence)).map(t=>`<div class="business-tax-row"><span class="category-icon">${icon('calendar')}</span><div class="bill-info"><strong>${e(t.name)}</strong><p>Competência ${e(t.competence.slice(5))}/${e(t.competence.slice(0,4))} · vence ${dateLabel(t.due_date)}</p></div><div class="business-pending-value"><b class="money">${money(t.amount)}</b>${t.paid?'<span class="business-status paid">Pagamento registrado</span>':`<button class="text-button" data-business-taxpay="${e(t.id)}">Registrar pagamento${icon('check')}</button>`}</div></div>`).join('')||`<div class="empty">Adicione ${mei?'o DAS':'um tributo'} com a competência,<br>o vencimento e o valor do documento.</div>`}<p class="form-note">Os valores não são apurados pela Alva. O registro de pagamento cria uma saída no caixa da empresa, sem duplicidade.</p></section><aside class="panel business-resources">${panelHeader('Atalhos oficiais para MEI','Consulte os serviços do governo')}<a class="business-resource" href="https://www.gov.br/pt-br/servicos/emitir-das-para-pagamento-de-tributos-do-mei" target="_blank" rel="noopener noreferrer"><span>${icon('debt')}Emissão do DAS no portal oficial</span>↗</a><a class="business-resource" href="https://www.gov.br/pt-br/servicos/baixar-relatorio-mensal-de-receitas-brutas" target="_blank" rel="noopener noreferrer"><span>${icon('download')}Relatório mensal de receitas brutas</span>↗</a><p class="form-note">Os serviços acima são destinados ao MEI. Selecione o tipo do seu negócio no perfil e confira suas obrigações com o profissional responsável. A Alva oferece controle gerencial e não transmite declarações ou documentos fiscais.</p></aside></div>`;}
 function profileModal(){const p=get().profile;modal('Perfil da empresa',`<div class="form-grid"><label class="field full">Nome do negócio<input class="input" name="name" value="${e(p.name)}" placeholder="Ex.: meu estúdio" maxlength="70" required></label><label class="field">Tipo de negócio<select name="company_type">${['MEI','Microempresa','Autônomo','Outro'].map(v=>`<option ${p.kind===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('CNPJ (opcional)','cnpj','text',p.cnpj,'maxlength="20"',false)}${field('Caixa inicial (R$)','opening','number',numeric(p.opening_balance),'min="-100000000" max="100000000" step="0.01"')}${field('Meta anual de vendas (R$)','goal','number',numeric(p.annual_goal),'min="0" max="100000000" step="0.01"')}</div><p class="form-note">Caixa inicial é o valor disponível antes das movimentações cadastradas. A meta anual é um objetivo do negócio, não um limite fiscal.</p>`,'business-profile-form','Salvar perfil');}
 function recordModal(id){const r=get().records.find(r=>r.id===id);if(r?.linked)throw new Error('Este registro está vinculado a outra operação.');modal(r?'Editar movimentação':'Movimentação do negócio',`<input type="hidden" name="record_id" value="${e(r?.id||'')}"><div class="form-grid"><label class="field full">Descrição<input class="input" name="record_title" autocomplete="off" autocorrect="off" spellcheck="false" value="${e(r?.name||'')}" maxlength="100" placeholder="Ex.: venda, serviço ou compra de materiais" required></label>${field('Valor (R$)','amount','number',r?numeric(r.amount):'','min="0.01" max="100000000" step="0.01"')}<label class="field">Tipo<select name="type"><option value="income" ${r?.type==='income'?'selected':''}>Receita / venda</option><option value="expense" ${r?.type==='expense'?'selected':''}>Despesa</option></select></label><label class="field full business-sale-option"><span><input type="checkbox" name="counts_as_sale" ${r?.counts_as_sale!==false?'checked':''}> Somar esta entrada ao faturamento de vendas</span></label><label class="field full">Cliente ou fornecedor (opcional)<input class="input" name="counterparty" autocomplete="off" value="${e(r?.counterparty||'')}" maxlength="100"></label>${categoryField(ctx.getData(),'business',r?.type||'income',r?.category)}<label class="field">Situação<select name="status"><option value="paid" ${r?.status==='paid'?'selected':''}>Já recebido / pago</option><option value="pending" ${r?.status==='pending'?'selected':''}>A receber / a pagar</option></select></label>${field('Data da venda/despesa','date','date',r?.date||dateISO(),`max="${dateISO()}"`)}${field('Vencimento','due_date','date',r?.due_date||dateISO())}${field('Data da baixa','paid_date','date',r?.paid_date||dateISO(),`max="${dateISO()}"`)}</div><p class="form-note">Se estiver pendente, a data da baixa será ignorada. A venda entra no faturamento pela data do registro.</p>`,'business-record-form','Salvar movimentação');}
 function deleteModal(id){
  const {record,counterpart,tax}=businessRecordDeletion(ctx.getData(),id);
  const effect=counterpart?'A entrada vinculada no Pessoal também será removida.':
   tax?'O tributo voltará para A pagar.':'Os totais do negócio serão recalculados.';
  modal('Excluir movimentação?',`<input type="hidden" name="record_id" value="${e(id)}">
   <p class="form-note"><strong>${e(record.name)}</strong> · ${money(record.amount)}</p>
   <p class="form-note">${effect}</p>`,'business-delete-form','Excluir movimentação');
 }
 function settleModal(id,tax=false){const r=(tax?get().taxes:get().records).find(r=>r.id===id);if(!r||(tax?r.paid:r.status!=='pending'))throw new Error('Este item não está mais pendente.');modal(tax?'Registrar pagamento do tributo':r.type==='income'?'Registrar recebimento':'Registrar pagamento',`<input type="hidden" name="record_id" value="${e(id)}"><input type="hidden" name="entity" value="${tax?'tax':'record'}"><p class="business-confirm"><strong>${e(r.name)}</strong><span class="money">${money(r.amount)}</span></p>${field('Data da baixa','paid_date','date',dateISO(),`max="${dateISO()}"`)}<p class="form-note">Confirme após receber ou pagar o valor integral. Esta ação atualiza o seu controle de caixa e não movimenta sua conta bancária.</p>`,'business-settle-form','Confirmar registro');}
 function taxModal(){const b=get();modal('Adicionar tributo',`<div class="form-grid">${field('Descrição','name','text',b.profile.kind==='MEI'?'DAS-MEI':'Tributo','maxlength="70"')}${field('Competência','competence','month',month())}${field('Valor do documento (R$)','amount','number','','min="0.01" max="100000000" step="0.01"')}${field('Vencimento do documento','due_date','date',dateISO())}</div><p class="form-note">Copie o valor e o vencimento da guia oficial. A Alva não calcula o tributo nem gera código de pagamento.</p>`,'business-tax-form','Adicionar tributo');}
 function withdrawalModal(amount){const today=noticeDate();modal('Retirada para o titular',`${field('Valor da retirada (R$)','amount','number',amount?numeric(amount):'','min="0.01" max="100000000" step="0.01"')}${field('Data da retirada','date','date',today,`max="${today}"`)}<p class="form-note">Será registrada uma saída no negócio e uma entrada vinculada no seu controle pessoal. O registro é gerencial e não define o tratamento tributário da retirada.</p>`,'business-withdrawal-form','Registrar retirada');}
 function filter(){const q=(document.querySelector('#business-search')?.value||'').toLowerCase(),type=document.querySelector('#business-type-filter')?.value,category=document.querySelector('#business-category-filter')?.value;const list=get().records.filter(r=>r.date.startsWith(month())&&(r.name+' '+r.counterparty).toLowerCase().includes(q)&&(type==='all'||r.type===type)&&(!category||r.category===category)).slice().sort((a,b)=>b.date.localeCompare(a.date));document.querySelector('#business-record-results').innerHTML=table(list);}
 async function click(button){if(button.dataset.businessDelete){deleteModal(button.dataset.businessDelete);return true;}if(button.dataset.businessSettle){settleModal(button.dataset.businessSettle);return true;}if(button.dataset.businessTaxpay){settleModal(button.dataset.businessTaxpay,true);return true;}if(button.dataset.businessEdit){recordModal(button.dataset.businessEdit);return true;}const a=button.dataset.business;if(!a)return false;if(a==='profile')profileModal();if(a==='record')recordModal();if(a==='tax')taxModal();if(a==='withdrawal')withdrawalModal();if(a==='export'){const url=URL.createObjectURL(new Blob([businessCSV(get(),month())],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`alva-negocio-${month()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Movimentações da empresa exportadas.');}return true;}
 async function submit(form){const id=form.getAttribute('id');if(!id.startsWith('business-'))return false;const f=Object.fromEntries(new FormData(form));
  if(id==='business-delete-form'){
   await commit(next=>deleteBusinessRecord(next,f.record_id),'Movimentação excluída.');
   return true;
  }
  const amount=Math.round(Number(f.amount)*100);const recName=String(f.record_title??f.name??'');await commit(next=>{const b=ensureBusiness(next);if(id==='business-profile-form'){if(!recName.trim())throw new Error('Informe o nome do negócio.');b.profile={name:recName.trim(),kind:f.company_type,cnpj:f.cnpj.trim(),opening_balance:Math.round(Number(f.opening)*100),annual_goal:Math.round(Number(f.goal)*100)};}if(id==='business-record-form'){const record={name:recName,amount,type:f.type,status:f.status,category:categoryForRecord(next,'business',f),counterparty:f.counterparty.trim(),date:f.date,due_date:f.due_date,counts_as_sale:f.type==='income'&&f.counts_as_sale==='on',paid_date:f.status==='paid'?f.paid_date:null};if(record.status==='paid'&&record.paid_date<record.date)throw new Error('A data da baixa deve ser igual ou posterior à data do registro.');if(f.record_id){const index=b.records.findIndex(r=>r.id===f.record_id&&!r.linked);if(index<0)throw new Error('Registro não encontrado.');if(!record.name.trim()||!Number.isSafeInteger(amount)||amount<=0)throw new Error('Revise a descrição e o valor.');b.records[index]={...b.records[index],...record,id:f.record_id,name:record.name.trim()};}else addBusinessRecord(next,record);}if(id==='business-tax-form')addBusinessTax(next,{name:recName.trim(),amount,competence:f.competence,due_date:f.due_date});if(id==='business-settle-form'){if(f.entity==='tax')payBusinessTax(next,f.record_id,f.paid_date);else{const r=b.records.find(r=>r.id===f.record_id);if(r&&f.paid_date<r.date)throw new Error('A baixa não pode ser anterior à data do registro.');settleBusinessRecord(next,f.record_id,f.paid_date);}}if(id==='business-withdrawal-form')ownerWithdrawal(next,amount,f.date);},id==='business-withdrawal-form'?'Retirada registrada no negócio e no pessoal.':'Controle do negócio atualizado.');return true;}
 return {render,setSection,click,submit,filter,openPending:settleModal,openWithdrawal:withdrawalModal};
}
